<?php $chartMax = max([1,...array_map(fn ($m) => max((int) $m['income'],(int) $m['expense']), $report['months'])]); ?>
<div class="chart-legend"><span><i class="legend-dot income-dot"></i><?= e(t('Income')) ?></span><span><i class="legend-dot expense-dot"></i><?= e(t('Expense')) ?></span><span class="muted"><?= e(t('MMK')) ?></span></div>
<?php if (!$report['months']): ?><div class="chart-empty"><div class="empty-grid"></div><p><?= e(t('Your cash flow story starts with your first record.')) ?></p></div><?php else: ?>
<div class="bar-chart" role="img" aria-label="<?= e(t('Monthly income and expenses in MMK')) ?>">
<?php foreach ($report['months'] as $month): ?><div class="bar-group"><div class="bar-pair"><div class="chart-bar income-bar" style="height:<?= max(1, round((int) $month['income']/$chartMax*100,2)) ?>%" title="<?= e($month['month'] . ' · ' . t('Income') . ': ' . money($month['income'])) ?>"></div><div class="chart-bar expense-bar" style="height:<?= max(1, round((int) $month['expense']/$chartMax*100,2)) ?>%" title="<?= e($month['month'] . ' · ' . t('Expense') . ': ' . money($month['expense'])) ?>"></div></div><span><?= e($month['month']) ?></span><small class="sr-only"><?= e(t('Income') . ': ' . money($month['income']) . '; ' . t('Expense') . ': ' . money($month['expense'])) ?></small></div><?php endforeach ?></div>
<?php endif ?>
